package com.j256.ormlite.table;

import static org.junit.jupiter.api.Assertions.assertThrowsExactly;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.sql.SQLException;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import com.j256.ormlite.BaseCoreTest;
import com.j256.ormlite.dao.Dao;
import com.j256.ormlite.field.DatabaseField;
import com.j256.ormlite.h2.H2DatabaseType;

public class SchemaUtilsTest extends BaseCoreTest {

	private final static String SCHEMA_NAME = "schema";

	@Override
	@BeforeEach
	public void before() throws Exception {
		super.before();
	}

	@Test
	public void testCreateSchema() throws SQLException {
		SchemaUtils.dropSchema(connectionSource, Schema.class, true);
		assertTrue(SchemaUtils.createSchema(connectionSource, Schema.class) > 0);
	}

	@Test
	public void testCreateSchemaName() throws SQLException {
		SchemaUtils.dropSchema(connectionSource, SCHEMA_NAME, true);
		assertTrue(SchemaUtils.createSchema(connectionSource, SCHEMA_NAME) > 0);
	}

	@Test
	public void testCreateSchemaDao() throws SQLException {
		Dao<Schema, Integer> dao = createDao(Schema.class, false);
		SchemaUtils.dropSchema(connectionSource, Schema.class, true);
		assertTrue(SchemaUtils.createSchema(dao) > 0);
	}

	@Test
	public void testCreateIfNotExists() throws SQLException {
		SchemaUtils.dropSchema(connectionSource, Schema.class, true);
		SchemaUtils.dropSchema(connectionSource, SCHEMA_NAME, true);
		assertTrue(SchemaUtils.createSchemaIfNotExists(connectionSource, Schema.class) > 0);
		assertTrue(SchemaUtils.createSchemaIfNotExists(connectionSource, SCHEMA_NAME) > 0);
	}

	@Test
	public void testCreateSchemaStatements() throws SQLException {
		assertTrue(SchemaUtils.getCreateSchemaStatements(new H2DatabaseType(), SCHEMA_NAME).size() > 0);
	}

	@Test
	public void testDropSchema() throws SQLException {
		SchemaUtils.dropSchema(connectionSource, Schema.class, true);
		assertTrue(SchemaUtils.createSchema(connectionSource, Schema.class) > 0);
		assertTrue(SchemaUtils.dropSchema(connectionSource, Schema.class, true) > 0);
		assertTrue(SchemaUtils.createSchema(connectionSource, Schema.class) > 0);
		assertTrue(SchemaUtils.dropSchema(connectionSource, Schema.class, true) > 0);
		// this will generate errors but we ignore them
		assertTrue(SchemaUtils.dropSchema(connectionSource, Schema.class, true) > 0);
	}

	@Test
	public void testDropSchemaThrow() throws SQLException {
		// make sure it is gone
		SchemaUtils.dropSchema(connectionSource, Schema.class, true);
		// now drop it while _not_ ignoring errors
		assertThrowsExactly(SQLException.class, () -> {
			SchemaUtils.dropSchema(connectionSource, Schema.class, false);
		});
	}

	@DatabaseTable(tableName = "table", schemaName = SCHEMA_NAME)
	protected static class Schema {
		@DatabaseField(generatedId = true)
		public int id;
		@DatabaseField
		public int val;

		public Schema() {
			// needed for ormlite
		}
	}
}

package com.j256.ormlite;

import java.sql.SQLException;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;

import com.j256.ormlite.dao.BaseDaoImpl;
import com.j256.ormlite.dao.Dao;
import com.j256.ormlite.dao.DaoManager;
import com.j256.ormlite.db.DatabaseType;
import com.j256.ormlite.field.DatabaseField;
import com.j256.ormlite.h2.H2ConnectionSource;
import com.j256.ormlite.h2.H2DatabaseType;
import com.j256.ormlite.misc.WrappedConnectionSource;
import com.j256.ormlite.support.ConnectionSource;
import com.j256.ormlite.table.DatabaseTable;
import com.j256.ormlite.table.DatabaseTableConfig;
import com.j256.ormlite.table.SchemaUtils;
import com.j256.ormlite.table.TableUtils;

public abstract class BaseCoreTest {

	public static final String FOO_TABLE_NAME = "foo";
	public static final String NOID_TABLE_NAME = "noid";

	protected DatabaseType databaseType;
	protected WrappedConnectionSource connectionSource;

	/**
	 * @throws Exception
	 *             For sub-classes.
	 */
	@BeforeEach
	public void before() throws Exception {
		connectionSource = new WrappedConnectionSource(new H2ConnectionSource());
		databaseType = connectionSource.getDatabaseType();
		DaoManager.clearCache();
	}

	@AfterEach
	public void after() throws Exception {
		connectionSource.close();
		connectionSource = null;
	}

	protected <T, ID> Dao<T, ID> createDao(Class<T> clazz, boolean createTable) throws SQLException {
		if (connectionSource == null) {
			throw new SQLException("Connection source is null");
		}
		@SuppressWarnings("unchecked")
		BaseDaoImpl<T, ID> dao = (BaseDaoImpl<T, ID>) DaoManager.createDao(connectionSource, clazz);
		return configDao(connectionSource, dao, createTable);
	}

	protected <T, ID> Dao<T, ID> createDao(ConnectionSource connectionSource, Class<T> clazz, boolean createTable)
			throws SQLException {
		@SuppressWarnings("unchecked")
		BaseDaoImpl<T, ID> dao = (BaseDaoImpl<T, ID>) DaoManager.createDao(connectionSource, clazz);
		return configDao(connectionSource, dao, createTable);
	}

	protected <T, ID> Dao<T, ID> createDao(DatabaseTableConfig<T> tableConfig, boolean createTable)
			throws SQLException {
		if (connectionSource == null) {
			throw new SQLException("Connection source is null");
		}
		@SuppressWarnings("unchecked")
		BaseDaoImpl<T, ID> dao = (BaseDaoImpl<T, ID>) DaoManager.createDao(connectionSource, tableConfig);
		return configDao(connectionSource, dao, createTable);
	}

	protected <T> void createTable(Class<T> clazz, boolean dropAtEnd) throws SQLException {
		createTable(connectionSource, DatabaseTableConfig.fromClass(databaseType, clazz), dropAtEnd);
	}

	protected <T> void dropTable(Class<T> clazz, boolean ignoreErrors) throws SQLException {
		// drop the table and ignore any errors along the way
		TableUtils.dropTable(connectionSource, clazz, ignoreErrors);
	}

	protected <T, ID> Dao<T, ID> configDao(BaseDaoImpl<T, ID> dao, boolean createTable) throws SQLException {
		return configDao(connectionSource, dao, createTable);
	}

	protected <T, ID> Dao<T, ID> configDao(ConnectionSource connectionSource, BaseDaoImpl<T, ID> dao,
			boolean createTable) throws SQLException {
		if (connectionSource == null) {
			throw new SQLException("Connection source is null");
		}
		if (createTable) {
			DatabaseTableConfig<T> tableConfig = dao.getTableConfig();
			if (tableConfig == null) {
				tableConfig = DatabaseTableConfig.fromClass(databaseType, dao.getDataClass());
			}
			if (tableConfig.getSchemaName() != null && tableConfig.getSchemaName().length() > 0) {
				SchemaUtils.createSchema(connectionSource, tableConfig.getSchemaName());
			}
			createTable(connectionSource, tableConfig, true);
		}
		return dao;
	}

	private <T> void createTable(ConnectionSource connectionSource, DatabaseTableConfig<T> tableConfig,
			boolean dropAtEnd) throws SQLException {
		try {
			// first we drop it in case it existed before
			TableUtils.dropTable(connectionSource, tableConfig, true);
		} catch (SQLException ignored) {
			// ignore any errors about missing tables
		}
		TableUtils.createTable(connectionSource, tableConfig);
	}

	protected static class LimitAfterSelectDatabaseType extends H2DatabaseType {

		// needed for exception
		public LimitAfterSelectDatabaseType() throws SQLException {
			super();
		}

		@Override
		public boolean isLimitAfterSelect() {
			return true;
		}
	}

	@DatabaseTable(tableName = FOO_TABLE_NAME)
	protected static class Foo {
		public static final String ID_COLUMN_NAME = "id";
		public static final String VAL_COLUMN_NAME = "val";
		public static final String EQUAL_COLUMN_NAME = "equal";
		public static final String STRING_COLUMN_NAME = "string";
		@DatabaseField(generatedId = true, columnName = ID_COLUMN_NAME)
		public int id;
		@DatabaseField(columnName = VAL_COLUMN_NAME)
		public int val;
		@DatabaseField(columnName = EQUAL_COLUMN_NAME)
		public int equal;
		@DatabaseField(columnName = STRING_COLUMN_NAME)
		public String stringField;

		public Foo() {
		}

		@Override
		public String toString() {
			return "Foo:" + id;
		}

		@Override
		public boolean equals(Object other) {
			if (other == null || other.getClass() != getClass())
				return false;
			return id == ((Foo) other).id;
		}

		@Override
		public int hashCode() {
			return id;
		}
	}

	@DatabaseTable(schemaName = "FOO_SCHEMA", tableName = FOO_TABLE_NAME)
	protected static class SchemaFoo {
		public static final String ID_COLUMN_NAME = "id";
		public static final String VAL_COLUMN_NAME = "val";
		public static final String EQUAL_COLUMN_NAME = "equal";
		public static final String STRING_COLUMN_NAME = "string";
		@DatabaseField(generatedId = true, columnName = ID_COLUMN_NAME)
		public int id;
		@DatabaseField(columnName = VAL_COLUMN_NAME)
		public int val;
		@DatabaseField(columnName = EQUAL_COLUMN_NAME)
		public int equal;
		@DatabaseField(columnName = STRING_COLUMN_NAME)
		public String stringField;

		public SchemaFoo() {
		}

		@Override
		public String toString() {
			return "Foo:" + id;
		}

		@Override
		public boolean equals(Object other) {
			if (other == null || other.getClass() != getClass())
				return false;
			return id == ((Foo) other).id;
		}

		@Override
		public int hashCode() {
			return id;
		}
	}

	protected static class Foreign {
		public static final String FOO_COLUMN_NAME = "foo_id";
		@DatabaseField(generatedId = true)
		public int id;
		@DatabaseField(foreign = true, columnName = FOO_COLUMN_NAME)
		public Foo foo;

		public Foreign() {
		}
	}

	protected static class ForeignSchemaFoo {
		public static final String FOO_COLUMN_NAME = "foo_id";
		@DatabaseField(generatedId = true)
		public int id;
		@DatabaseField(foreign = true, columnName = FOO_COLUMN_NAME)
		public SchemaFoo foo;

		public ForeignSchemaFoo() {
		}
	}

	@DatabaseTable(tableName = NOID_TABLE_NAME)
	protected static class NoId {
		@DatabaseField
		public String stuff;

		public NoId() {
		}
	}
}

